import React, { useEffect, useState } from 'react'
import { connect } from 'react-redux'
import { Icon, Row, Col, Tag, notification, Spin } from 'antd'
import moment from 'moment-timezone'
import LayoutContent from '../../../components/utility/layoutContent'
import LayoutContentWrapper from '../../../components/utility/layoutWrapper'
import TableWrapper from './pagination.style'
import { HARDCOPY_STATUS_COLOR, HARDCOPY_STATUS_LABEL, HARDCOPY_STATUS_OPTIONS } from './enum'
import hardcopyActions from '../../redux/hardcopy/actions'
import loadingActions from '../../../redux/loading/actions'
import errorActions from '../../../redux/error/actions'

const { listHardcopy, resetHardcopyState } = hardcopyActions
const { resetLoadingRedux } = loadingActions
const { resetErrorRedux } = errorActions

const PAGE_SIZE = 10

const HardcopyList = ({ history, listData, listMeta, listMessage, loading, listHardcopy, resetHardcopyState, resetLoadingRedux, resetErrorRedux }) => {
  const [filterStatus, setFilterStatus] = useState('')
  const [currentPage, setCurrentPage] = useState(1)

  const fetchList = ({ status = filterStatus, page = currentPage } = {}) => {
    listHardcopy({
      limit: PAGE_SIZE,
      offset: (page - 1) * PAGE_SIZE,
      ...(status ? { status } : {})
    })
  }

  useEffect(() => {
    fetchList()
    return () => {
      resetHardcopyState(['listData', 'listMeta', 'listMessage'])
      resetLoadingRedux(['LIST_HARDCOPY'])
      resetErrorRedux(['LIST_HARDCOPY'])
    }
  }, [])

  useEffect(() => {
    if (listMessage && listMessage !== 'success') {
      notification.error({ message: listMessage })
      resetHardcopyState(['listMessage'])
    }
  }, [listMessage])

  const handleTableChange = (pagination, filters) => {
    const selectedStatus = filters.current_status?.[0] || ''
    const newPage = selectedStatus !== filterStatus ? 1 : pagination.current
    setFilterStatus(selectedStatus)
    setCurrentPage(newPage)
    fetchList({ status: selectedStatus, page: newPage })
  }

  const handleViewDetail = (record) => {
    history.push(`/hardcopy-management/${record.internal_id}`)
  }

  const columns = [
    {
      key: 'action',
      title: '',
      width: 50,
      render: (_, record) => (
        <Icon
          type='eye'
          style={{ fontSize: 16, cursor: 'pointer', color: '#1890ff' }}
          onClick={() => handleViewDetail(record)}
        />
      )
    },
    {
      key: 'current_status',
      title: 'Status',
      dataIndex: 'current_status',
      filters: HARDCOPY_STATUS_OPTIONS.map((s) => ({ text: <Tag color={HARDCOPY_STATUS_COLOR[s]}>{HARDCOPY_STATUS_LABEL[s] || s}</Tag>, value: s })),
      filterMultiple: false,
      filteredValue: filterStatus ? [filterStatus] : null,
      render: (status) => (
        <Tag color={HARDCOPY_STATUS_COLOR[status] || 'default'}>
          {HARDCOPY_STATUS_LABEL[status] || status || '-'}
        </Tag>
      )
    },
    {
      key: 'latest_updated_at',
      title: 'Latest Update At',
      dataIndex: 'latest_updated_at',
      render: (date) => date ? moment(date).tz('Asia/Jakarta').format('DD MMM YYYY HH:mm') : '-'
    },
    {
      key: 'requested_at',
      title: 'Requested At',
      dataIndex: 'requested_at',
      render: (date) => date ? moment(date).tz('Asia/Jakarta').format('DD MMM YYYY HH:mm') : '-'
    },
    {
      key: 'awb',
      title: 'AWB',
      dataIndex: 'awb',
      render: (val) => val || '-'
    },
    {
      key: 'reference_id',
      title: 'Reference ID',
      dataIndex: 'reference_id',
      render: (val) => val || '-'
    },
    {
      key: 'application_number',
      title: 'Application Number',
      dataIndex: 'application_number',
      render: (val) => val || '-'
    },
    {
      key: 'policy_number',
      title: 'Policy Number',
      dataIndex: 'policy_number',
      render: (val) => val || '-'
    },
    {
      key: 'provider_name',
      title: 'Provider Name',
      dataIndex: 'provider_name',
      render: (val) => val || '-'
    },
    {
      key: 'partner_name',
      title: 'Partner Name',
      dataIndex: 'partner_name',
      render: (val) => val || '-'
    },
    {
      key: 'product_name',
      title: 'Product Name',
      dataIndex: 'product_name',
      render: (val) => val || '-'
    },
    {
      key: 'package_name',
      title: 'Package Name',
      dataIndex: 'package_name',
      render: (val) => val || '-'
    }
  ]

  return (
    <LayoutContentWrapper>
      <LayoutContent>
        <Row style={{ marginBottom: 16 }}>
          <Col span={24}>
            <h2><b>Hardcopy List</b></h2>
          </Col>
        </Row>
        <Spin spinning={!!loading}>
          <TableWrapper
            columns={columns}
            bordered
            rowKey={(record) => record.internal_id}
            dataSource={listData}
            pagination={{
              current: currentPage,
              pageSize: PAGE_SIZE,
              total: listMeta?.count,
              showSizeChanger: false
            }}
            onChange={handleTableChange}
            className='isoSearchableTable'
            scroll={{ x: true }}
          />
        </Spin>
      </LayoutContent>
    </LayoutContentWrapper>
  )
}

export default connect(
  (state) => ({
    listData: state.Hardcopy.listData,
    listMeta: state.Hardcopy.listMeta,
    listMessage: state.Hardcopy.listMessage,
    loading: state.Loading.LIST_HARDCOPY
  }),
  { listHardcopy, resetHardcopyState, resetLoadingRedux, resetErrorRedux }
)(HardcopyList)
